/**
 * WriteInCover
 *
 * The write-in that covers a space, wherever in the tree it was recorded.
 *
 * A write-in names ONE unit, but it is a fact about a physical space, and a
 * building's space contains its rooms'. The board draws whichever level the
 * tree currently resolves to (`drawn_units`), and merging or splitting moves
 * that level under staff's feet -- so a write-in recorded on a merged
 * building went silent the moment somebody split it back to rooms, and one
 * recorded on a room said nothing on the building's card after a merge. Both
 * left the same hole: a family could be dropped into a space somebody is
 * already sleeping in.
 *
 * Resolved on READ, never cascaded on write. A row per leaf would duplicate
 * one fact across rows that then drift -- clear one room and the others still
 * close the space -- and would strand orphans behind a re-merge. There is
 * still exactly one `lodging_write_ins` row (kindred#2382 moved occupancy off
 * `lodging_availability`, which now answers only the staff<->family role);
 * this says which units it covers, and `unit_id` is the row it belongs to, so
 * a card that inherited the write-in can still clear it at the source rather
 * than dead-ending.
 */
export type WriteInCover = {
  /**
   * Unit Id
   */
  unit_id?: string
  /**
   * Unit Code
   */
  unit_code?: string
  /**
   * Unit Name
   */
  unit_name?: string
  /**
   * Occupant Name
   */
  occupant_name?: string
  /**
   * Note
   */
  note?: string
  /**
   * Party Size
   */
  party_size?: number | null
  /**
   * Relation
   */
  relation?: 'own' | 'ancestor' | 'descendant'
  /**
   * Unit Sleeps
   */
  unit_sleeps?: number | null
  bunking_request?: BunkingRequestSummary | null
}

/**
 * WriteInDeleteRequest
 *
 * Remove ONE occupant from one unit, leaving everything else standing.
 *
 * kindred#2583 step 7. `PUT /availability` with `family_available: null`
 * stays the CLEAR-THIS-UNIT-ENTIRELY verb -- it drops the role row and every
 * occupancy row on the unit, which is exactly what it means today while a
 * unit can hold one. This is the other half: "take Chen out of the shared
 * cabin and leave Johnson where she is."
 *
 * ADDRESSED BY IDENTITY, NOT BY RECORD ID, following
 * `PlacementDeleteRequest` and `DELETE /api/lodging/placements`: the row is
 * named by values the client already holds, and a write-in's record id is
 * not among them (Design A, which would have published one, was declined).
 * Under Design B `(unit_id, occupant_name)` is that identity.
 *
 * `occupant_name` is REQUIRED here, unlike on the write request above,
 * because it is the whole address rather than a payload field. There is no
 * "remove the unnamed one" — that is what the clear verb is for.
 *
 * ⚠️ OQ-8. The spec marks this shape "verify against staff expectation
 * before building". It is the recommended one and stays cheap to revise
 * while the feature is dark behind the unique index.
 */
export type WriteInDeleteRequest = {
  /**
   * Year
   */
  year: number
  /**
   * Session Cm Id
   */
  session_cm_id: number
  /**
   * Scenario
   *
   * saved_scenarios record id; blank is the live board
   */
  scenario?: string
  /**
   * Unit Id
   */
  unit_id: string
  /**
   * Occupant Name
   */
  occupant_name: string
}

